<?php use CMS\Core\Csrf; ?>
<header class="page-header editor-header"><div><a class="back-link" href="<?= e(admin_url('/components/'.(int)$component['id'].'/edit')) ?>">← <?= e($component['name']) ?></a><p class="eyebrow">Component field</p><h1><?= $fieldId?'Edit field':'Add field' ?></h1></div></header>
<?php if ($errors): ?><div class="alert error"><ul><?php foreach ($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<form method="post" action="<?= e($fieldId?admin_url('/components/'.(int)$component['id'].'/fields/'.$fieldId.'/edit'):admin_url('/components/'.(int)$component['id'].'/fields/new')) ?>" class="card editor-card stack" data-schema-field-form><?= Csrf::field() ?><div class="form-grid two"><label>Label<input name="label" value="<?= e($field['label']) ?>" required data-field-label></label><label>Field type<select name="field_type" data-field-type><?php foreach ($types as $key=>$label): ?><option value="<?= e($key) ?>" <?= $field['field_type']===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label></div><details class="advanced-panel"><summary>Advanced field identity</summary><div class="form-grid two advanced-panel-body"><label>Internal field key<input name="field_key" value="<?= e($field['field_key']) ?>" <?= $fieldId?'readonly':'' ?> data-field-key><small class="field-help"><?= $fieldId?'Stable after creation.':'Generated automatically from the label.' ?></small></label><label>Order<input type="number" name="sort_order" value="<?= (int)$field['sort_order'] ?>"></label></div></details><label>Placeholder<input name="placeholder" value="<?= e($field['placeholder']??'') ?>"></label><label>Help text<textarea name="help_text" rows="2"><?= e($field['help_text']??'') ?></textarea></label><label class="confirm-check"><input type="checkbox" name="is_required" value="1" <?= (int)($field['is_required']??0)===1?'checked':'' ?>> Required</label><div class="field-type-options" data-options-for="select multiselect"><label>Options<textarea name="options" rows="6"><?= e($field['options']??'') ?></textarea><small class="field-help">One option per line.</small></label></div><div class="field-type-options" data-options-for="number"><div class="form-grid three"><label>Minimum<input type="number" step="any" name="min" value="<?= e((string)($field['min']??'')) ?>"></label><label>Maximum<input type="number" step="any" name="max" value="<?= e((string)($field['max']??'')) ?>"></label><label>Step<input type="number" step="any" name="step" value="<?= e((string)($field['step']??'')) ?>"></label></div></div><div class="field-type-options" data-options-for="text textarea"><label>Maximum characters<input type="number" name="max_length" value="<?= e((string)($field['max_length']??'')) ?>"></label></div><div class="field-type-options" data-options-for="text textarea number boolean date datetime select multiselect email url"><label>Default value<input name="default_value" value="<?= e((string)($field['default_value']??'')) ?>" maxlength="1000" placeholder="Optional"></label></div><button class="button" type="submit"><?= $fieldId?'Save field':'Add field' ?></button></form>
<?php if ($fieldId): ?><?php $inUse=CMS\Core\ContentModels::componentInUse((int)$component['id']); ?><section class="danger-zone"><div><strong><?= $inUse?'Archive field':'Delete unused field' ?></strong><p><?= $inUse?'This component is already used by a content model. Archiving hides this field from future editing while preserving existing nested values.':'This component is not currently used by a model, so the field definition can be removed.' ?></p></div><form method="post" action="<?= e(admin_url('/components/'.(int)$component['id'].'/fields/'.$fieldId.'/delete')) ?>"><?= Csrf::field() ?><?php if ($inUse): ?><label class="confirm-check"><input type="checkbox" name="confirm_archive" value="1" required> Preserve existing values and archive this component field.</label><button class="button danger">Archive field</button><?php else: ?><label class="confirm-check"><input type="checkbox" name="confirm_delete" value="1" required> Permanently delete this unused field definition.</label><button class="button danger">Delete field</button><?php endif; ?></form></section><?php endif; ?><script src="/assets/js/schema-fields.js?v=<?= e(app_version()) ?>" defer></script>
